    'ConnectivityVisualizerDesc'              => 'Interaktive Grafik, die zeigt, wie Risiken, Assets, Kontrollen und Frameworks zusammenhängen.',
    'RisksAndAssetsDesc'                      => 'Querverweis zwischen offenen Risiken und den Assets, die sie betreffen.',
