    'DocumentControlMappingDesc'              => 'Zuordnung von Governance-Dokumenten zu den Kontrollen, die sie dokumentieren.',

    // Incident Management reports (contributed by the IM Extra when enabled)
    'IncidentOverview'           => 'Vorfallübersicht',
