    'IncidentTrendDesc'          => 'Entwicklung des Vorfallaufkommens im Zeitverlauf, aufgeschlüsselt nach Art und Status.',
    'DynamicIncidentReportDesc'  => 'Konfigurierbarer Berichtsgenerator für Vorfälle mit Spalten-, Filter- und Gruppierungsoptionen.',
    'LessonsLearnedDesc'         => 'Erkenntnisse aus allen Vorfällen, mit Kontext des Quellvorfalls.',
    'IncidentDashboardDesc'      => 'Dashboard-Ansicht der KPIs für Vorfälle, der letzten Aktivitäten und der noch offenen Reaktionsmaßnahmen.',

