    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Konfigurieren Sie systemweite Einstellungen: Basis-URL, Sicherheit, Standardsprache, Zeitzone, Standardwerte für die Risikobewertung und mehr.',
    'SettingsPreferencesDesc'             => 'Standardwerte und Verhaltenseinstellungen in SimpleRisk: Sprache, Zeitzone, Audit-Status, Anforderungen an die Risikozuordnung, Schalter für das Verhalten der Benutzeroberfläche und Ähnliches.',
    'SettingsFileUploadDesc'              => 'Zulässige Dateitypen und Größenbeschränkungen für das Hochladen von Dateien in den verschiedenen Feldern für Dateianhänge.',
    'SettingsMailDesc'                    => 'SMTP-Konfiguration für ausgehende E-Mail-Benachrichtigungen, einschließlich Transport, Host, Authentifizierung und Antwortadresse.',
    'SettingsBackupsDesc'                 => 'Konfigurieren Sie Aufbewahrungsfristen, Zeitpläne und Download-Links für SimpleRisk-Datenbanksicherungen.',
    'SettingsSecurityDesc'                => 'Einstellungen für Authentifizierung, Sitzung, Passwortrichtlinie, Basis-URL und API-Sicherheit.',
    'SettingsLoggingDesc'                 => 'Konfiguration der Debug- und Audit-Protokollierung: Protokollierungsstufen, Aufbewahrungsdauer und Speicherort der Protokolldateien.',
    'HealthCheckDesc'                     => 'Diagnose des Systemstatus: PHP-Version, Erweiterungen, Dateiberechtigungen, Datenbankverbindung, Cron-Zeitplan und Extra-Aktivierungen.',
    'AnnouncementsDesc'                   => 'Erstellen und verwalten Sie Banner-Ankündigungen, die für alle Benutzer sichtbar sind.',
    'RegisterAndUpgradeDesc'              => 'Registrieren Sie Ihre SimpleRisk-Installation, geben Sie einen Abonnementschlüssel ein oder erneuern Sie ihn, und lösen Sie Core-/Extra-Upgrades mit einem Klick aus.',
    'QueueMonitorDesc'                    => 'Überprüfen Sie die Warteschlange der Hintergrundprozesse: ausstehende, laufende und fehlgeschlagene Prozesse.',
    'ExtrasDesc'                          => 'Aktivieren, deaktivieren und konfigurieren Sie SimpleRisk Extras (kostenpflichtige Zusatzmodule).',
    'ArtificialIntelligenceExtraDesc'     => 'Die Zusatzfunktion „Künstliche Intelligenz“ bietet eine erweiterte Risikoanalyse (einschließlich FAIR-Bewertungen) und eine maßgeschneiderte Dokumentation.',
    'CustomizationExtraDesc'              => 'Das Customization Extra ermöglicht es, verschiedene Feldtypen hinzuzufügen und zu entfernen und dynamisch benutzerdefinierte Seitenvorlagen zu erstellen.',
    'NotificationExtraDesc'               => 'Das E-Mail-Benachrichtigungs-Extra ermöglicht es SimpleRisk, E-Mail-Benachrichtigungen zu senden, wenn Risiken eingereicht, geändert oder anderweitig bearbeitet werden. Dieses Extra kann auch als geplantes Skript hinzugefügt werden, um regelmäßige Erinnerungen zu senden, wenn Risiken für eine Management-Überprüfung bereit sind. Im SimpleRisk-Core-Produkt werden ohne dieses Extra keine Benachrichtigungen außerhalb des Tools selbst übermittelt.',
    'VulnerabilityManagementExtraDesc'    => 'Das Vulnerability-Management-Extra ermöglicht es Kunden, ihre SimpleRisk-Instanz in Qualys, Tenable.io oder Rapid7 Nexpose/InsightVM zu integrieren und sowohl Asset- als auch Schwachstellendaten in SimpleRisk zu importieren. Von dort aus können Sie auswählen, welche Standorte abgedeckt werden sollen, festlegen, welche Schwachstellen-Punktzahlen importiert werden sollen, und priorisieren, welche Schwachstellen in Risiken umgewandelt werden, um sie nachzuverfolgen.',
    'IncidentManagementExtraDesc'         => 'Das Incident-Management-Extra basiert auf dem NIST 800-61 Computer Security Incident Handling Guide und bietet Funktionen für das Vorfallsmanagement innerhalb des SimpleRisk-Systems.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Benennen Sie die SimpleRisk-Terminologie (Risiko, Asset, Framework usw.) in der gesamten Benutzeroberfläche um.',
    'RiskConfigurationDesc'               => 'Regeln zur Risikobewertung konfigurieren: Stufen, Risikoappetit, SLA-Schwellenwerte und die klassischen bzw. beitragenden Risikoformeln.',
    'RiskAndThreatCatalogDesc'            => 'Pflegen Sie den Katalog der in den Dropdown-Menüs verwendeten Risiko- und Bedrohungswerte.',
    'AddAndRemoveValuesDesc'              => 'Verwalten Sie die Dropdown-Werte für Risikofelder: Standort, Quelle, Kategorie, Team, Technologie und mehr.',
    'AssetValuationDesc'                  => 'Konfigurieren Sie die Bewertungsskala für Vermögenswerte und die Bewertungsüberschreibungen pro Vermögenswert.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Benutzer hinzufügen, bearbeiten, deaktivieren und zurücksetzen; Passwortrichtlinie verwalten.',
    'RoleManagementDesc'                  => 'Definieren Sie Rollen und die Berechtigungen, die jede Rolle gewährt.',
    'TeamManagementDesc'                  => 'Teams erstellen und verwalten, die für die Filterung der Datensatzsichtbarkeit verwendet werden.',
    'SeparationExtraDesc'                 => 'Das Team-Based-Separation-Extra beschränkt die Anzeige von Risiken auf Benutzer, die Mitglieder des Teams sind, dem das Risiko zugewiesen ist. Im SimpleRisk-Core-Produkt kann ohne dieses Extra jeder Benutzer jedes Risiko sehen.',
    'CustomAuthenticationExtraDesc'       => 'Das Custom-Authentication-Extra bietet Unterstützung für Active Directory und SAML-Authentifizierung. Im SimpleRisk-Core-Produkt besteht ohne dieses Extra nur die Möglichkeit, neue Benutzer im SimpleRisk-Identitätsspeicher zu erstellen.',
    'EncryptionExtraDesc'                 => 'Die Erweiterung „Verschlüsselte Datenbank“ generiert einen zufälligen AES-256-Bit-Verschlüsselungsschlüssel und verschlüsselt damit sensible Daten, bevor diese in die SimpleRisk-Datenbank eingefügt werden. Dadurch wird verhindert, dass jemand die Daten ohne die direkte Verwendung der SimpleRisk-Anwendung einsehen oder ändern kann.',
    'OrganizationManagementDesc'          => 'Das Organizational-Hierarchy-Extra ermöglicht es, mehrere Geschäftseinheiten zu definieren, die beliebig viele Teams enthalten können. Benutzer können dann einem oder mehreren Teams unter verschiedenen Geschäftseinheiten zugewiesen werden. Dies wirkt sich darauf aus, welche Teams, Benutzer und Assets ein Benutzer sehen und verwenden kann, denen er nicht zugehörig ist.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Risiken in großen Mengen löschen. Sparsam einsetzen – Löschungen sind endgültig.',
    'AuditTrailDesc'                      => 'Das System-Auditprotokoll der Benutzeraktionen durchsuchen und exportieren.',
    'ImportExportExtraDesc'               => 'Das Import-Export-Extra ermöglicht den Datenimport in SimpleRisk durch die Zuordnung von Feldern in einer CSV-Datei zu Feldern in der SimpleRisk-Datenbank. So lassen sich beispielsweise Audit-Ergebnisse aus Tabellenkalkulationen von Drittanbietern, Ergebnisse von Schwachstellenscans aus anderen Tools, Assets aus Ihrer CMDB und vieles mehr importieren. Das Extra ermöglicht außerdem den Export von CSV-Dateien aus SimpleRisk, die Risiken, Risikominderungsmaßnahmen, Reviews oder einen kombinierten Bericht aller drei enthalten.',
    'JiraExtraDesc'                       => 'Das Jira Integration Extra ermöglicht Benutzern die bidirektionale Integration mit einer Jira-Instanz. Es ermöglicht die Verknüpfung von Risiken mit Jira-Vorgängen sowie die Synchronisierung ihrer Daten, ihres Status und ihrer Kommentare.',
    'APIExtraDesc'                        => 'Das API-Extra ermöglicht es Kunden, eine RESTful-API zu verwenden, um skriptgesteuerte Interaktionen mit anderen Anwendungen zu erstellen, erweiterte Automatisierung zu erzielen und vorhandene Infrastruktur zu nutzen.',
    'AdvancedSearchExtraDesc'             => 'Das Advanced-Search-Extra macht das Suchfeld der oberen Leiste zu einer einzigen Suche über Risiken, Frameworks, Kontrollen, Dokumente, Ausnahmen, Tests, Audits, Assets und Asset-Gruppen, mit einer vollständigen Suchseite zur Bearbeitung der Ergebnisse. Es zeigt nur Datensätze an, die der Benutzer sehen darf.',
    'AssessmentsExtraDesc'                => 'Das Risikobewertungs-Extra ermöglicht es Benutzern, Kontakte zu definieren, Fragen (einschließlich Logik) zu erstellen, mehrere Fragen mit einer Fragebogenvorlage zusammenzustellen, Fragebögen zu erstellen und an Kontakte zu senden, die Fragebogenergebnisse anzuzeigen, auf Grundlage dieser Ergebnisse Risiken hinzuzufügen, die Ergebnisse im Zeitverlauf zu vergleichen, extern angepasste Bewertungen zu importieren und zu exportieren und den Audit-Trail der Risikobewertung zu überprüfen.',
    'ActiveAssessmentsDesc'               => 'Laufende Bewertungen einsehen und verwalten.',
    'WorkflowsExtraDesc'                  => 'Das Workflows-Extra bietet eine visuelle, ereignisgesteuerte Workflow-Engine, die Aktionen des Risiko-Managements als Reaktion auf Ereignisse in SimpleRisk automatisiert. Sie können Workflows entwerfen, die bei Änderungen ausgelöst werden – etwa wenn ein Risiko eingereicht, aktualisiert oder überprüft wird –, um Genehmigungen weiterzuleiten, Aufgaben zuzuweisen und Ihren Prozess ohne manuelles Eingreifen am Laufen zu halten.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'Das Secure-Controls-Framework-(SCF)-Extra ist eine direkte Integration zwischen dem Secure Controls Framework und SimpleRisk. Es importiert den SCF-Katalog von Kontrollen und deren Zuordnungen zu einer Vielzahl von Compliance- und Cybersicherheits-Frameworks in die Governance-Funktionalität von SimpleRisk, sodass Sie die benötigten Frameworks übernehmen und deren Kontrollen verwalten können, ohne sie manuell aufzubauen.',

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Ältere varchar-Spalten für Überprüfungsdaten in geeignete Datumstypen migrieren. Nur sichtbar, wenn erforderlich.',
    'DatabaseUpgradeDesc'                 => 'Die SimpleRisk-Datenbank-Upgrade-Routine manuell auslösen.',

