    'AuditLog_ControlStatusAutoSynced' => 'Der Status der Kontrolle „{$short_name}“ wurde auf Grundlage der aktuellsten Testergebnisse automatisch auf „{$status_text}“ aktualisiert.',
    'EnableCSPHelp' => 'Die Content Security Policy (CSP) beschränkt den Browser darauf, Skripte, Stile, Bilder und Schriftarten ausschließlich von SimpleRisk selbst zu laden, und blockiert das Einbetten von Seiten in Frames sowie domänenübergreifende Formularübermittlungen. Sie ist die stärkste integrierte Abwehr gegen Cross-Site-Scripting. Lassen Sie sie aktiviert, es sei denn, sie steht im Konflikt mit einem Proxy, einer Browser-Erweiterung oder einer Integration von Drittanbietern in Ihrer Umgebung.',
    // Define Control Frameworks' Columns picker (Task: Columns picker + saved layout/filters) -- the "Standard" group label above its built-in fields (Family/Owner/Maturity/Status/Class/Phase/Priority/Type); 'CustomFields' already exists.
