    'SaveAndNew' => 'Speichern & Neu',
    'SaveAndView' => 'Speichern & Anzeigen',
    'ResetFormConfirmTitle' => 'Diese Risikoerfassung verwerfen?',
    'ResetFormConfirmBody' => 'Alle von Ihnen eingegebenen Informationen gehen verloren.',
    // Restore-template destructive confirm (Customization Extra, Save/Restore
    // action bar). Two body variants: risk's Details/Mitigation/Review tabs
    // named explicitly (the only fgroup with that 3-tab Cards layout), a
    // generic fallback for every other fgroup (single legacy-panel tab).
    // Both end on the same scoping reassurance -- confirmed via direct source
    // read that Restore only ever touches the currently-selected template
    // group, never any other.
    'RestoreTemplateConfirmTitle' => 'Standardlayout wiederherstellen?',
    'RestoreTemplateConfirmBodyRisk' => 'Dadurch wird jedes Feld auf den Registerkarten „Details“, „Minderung“ und „Überprüfung“ auf seine Standardwerte für diese Vorlagengruppe zurückgesetzt. Andere Vorlagengruppen sind nicht betroffen.',
    'RestoreTemplateConfirmBody' => 'Dadurch werden alle Felder dieser Vorlage für diese Vorlagengruppe auf ihre Standardwerte zurückgesetzt. Andere Vorlagengruppen sind davon nicht betroffen.',
    // CVSS holder's collapsed Temporal/Environmental/Impact-Modifiers
    // accordion (buildCvssHolder(), risk-details-form.js) -- these three
    // groups are optional CVSS v2 refinements on top of the required Base
    // Score Metrics, so they collapse behind this header by default.
    'AdvancedMetrics' => 'Erweiterte Metriken',
    // CVSS holder's Base Score Metrics sub-group headers (buildCvssHolder(),
    // risk-details-form.js) -- distinct from the existing 'ExploitabilityMetrics'/
    // 'ImpactMetrics' keys, which the legacy cvss_modal_content.php modal
    // still renders as plain "Exploitability Metrics"/"Impact Metrics" and
    // must keep unchanged. These fold the umbrella "Base Score Metrics"
    // heading into each sub-group's own header instead of a separate label.
    'BaseScoreExploitabilityMetrics' => 'Ausnutzbarkeitsmetriken der Basis-Punktzahl',
    'BaseScoreImpactMetrics' => 'Auswirkungsmetriken der Basis-Punktzahl',
    // Per-field help popovers on the CVSS holder's 14 metric selects
    // (buildCvssScoreItem(), risk-details-form.js) -- one per CVSS v2
    // metric, matching the standard CVSS v2 specification definitions.
    // Double-quoted (not single-quoted, this file's usual style) so the
    // \n line breaks are real escape sequences: each popover leads with one
    // overall sentence, then one bullet line per option, rendered via
    // white-space: pre-line on .sr-scoring-help-popover .popover-body
    // (scss/modules/_questionnaire.scss) -- plain text throughout, no HTML,
    // so the popover stays initialized without Bootstrap's `html: true`.
    "AttackVectorHelp" => 'Wie auf die Schwachstelle zugegriffen werden kann.
• Lokal: erfordert lokalen Zugriff, z. B. über eine Konsole oder Shell.
• Angrenzendes Netzwerk: Der Angreifer muss sich im selben physischen oder logischen Netzwerksegment befinden.
• Netzwerk: aus der Ferne über ein Netzwerk ausnutzbar, ohne dass lokaler oder angrenzender Zugriff erforderlich ist.',
    "AttackComplexityHelp" => 'Wie komplex der Angriff ist, sobald ein Angreifer Zugriff auf das Ziel hat.
• Hoch: erfordert spezielle Bedingungen, die schwer herzustellen sind.
• Mittel: Einige Bedingungen müssen erfüllt sein, die Ausnutzung ist dann aber nicht schwierig.
• Niedrig: Es sind keine besonderen Bedingungen erforderlich.',
    "AuthenticationHelp" => 'Wie oft sich ein Angreifer am Ziel authentifizieren muss, um es auszunutzen.
• Mehrfach: Die Authentifizierung ist zwei- oder mehrmals erforderlich, auch mit denselben Anmeldedaten.
• Einmal: Die Authentifizierung ist einmal erforderlich.
• Keine: Es ist keine Authentifizierung erforderlich.',
    "ConfidentialityImpactHelp" => "Die Auswirkungen auf die Vertraulichkeit der vom System verarbeiteten Daten im Falle einer Ausnutzung.\n• Keine: Keine Auswirkungen.\n• Teilweise: Offenlegung einiger Informationen, wobei der Angreifer nicht kontrollieren kann, welche, oder der Verlust ist begrenzt.\n• Vollständig: Vollständige Offenlegung aller Systeminformationen.",
    "IntegrityImpactHelp" => "Auswirkungen auf die Systemintegrität bei Ausnutzung.\n• Keine: Keine Auswirkungen.\n• Teilweise: Einige Daten können verändert werden, der Angreifer hat jedoch keine Kontrolle darüber, welche, oder der Umfang ist begrenzt.\n• Vollständig: Totale Kompromittierung der Systemintegrität; der Angreifer kann beliebige Dateien verändern.",
    "AvailabilityImpactHelp" => 'Die Auswirkung auf die Verfügbarkeit des Systems bei einer Ausnutzung.
• Keine: keine Auswirkung.
• Teilweise: verringerte Leistung oder Unterbrechungen der Verfügbarkeit.
• Vollständig: vollständiger Ausfall der betroffenen Ressource.',
    "RemediationLevelHelp" => 'Der Grad der verfügbaren Behebung für die Schwachstelle.
• Offizieller Fix: Eine vollständige Lösung des Herstellers ist verfügbar.
• Temporärer Fix: Ein offizieller, aber temporärer Fix ist verfügbar.
• Workaround: Es existiert ein inoffizieller Workaround, der nicht vom Hersteller stammt.
• Nicht verfügbar: Es ist keine Lösung verfügbar oder keine kann angewendet werden.',
    "ReportConfidenceHelp" => 'Der Grad des Vertrauens in die Existenz der Schwachstelle und die Glaubwürdigkeit ihrer technischen Details.
• Unbestätigt: ein einzelner, unbestätigter Quellbericht; das zugrunde liegende Problem ist spekulativ.
• Nicht belegt: Mehrere unabhängige Quellen berichten dasselbe Verhalten, aber die Grundursache ist nicht bestätigt.
• Bestätigt: Der Hersteller hat das Problem anerkannt, oder es wurde durch Quellcode- oder Exploit-Analyse bestätigt.',
    "CollateralDamagePotentialHelp" => 'Das Potenzial für den Verlust von Menschenleben, physischen Assets oder finanzielle Verluste, wenn die Schwachstelle ausgenutzt wird.
• Keines: Ein solcher Verlust ist unwahrscheinlich.
• Niedrig bis mittel: Ein mäßiger Verlust ist möglich.
• Hoch: eine katastrophale Auswirkung auf die Assets, den Umsatz oder die Sicherheit der Organisation.',
    "TargetDistributionHelp" => "Anteil der anfälligen Systeme in Ihrer Umgebung.\n• Keine: Keine Zielsysteme vorhanden.\n• Niedrig: 1–25 % der Systeme sind anfällig.\n• Mittel: 26–75 % sind anfällig.\n• Hoch: 76–100 % sind anfällig.",
    "ConfidentialityRequirementHelp" => 'Wie wichtig die Vertraulichkeit des betroffenen Assets für Ihre Organisation ist.
• Niedrig: Ein Vertraulichkeitsverlust hat eine begrenzte Auswirkung.
• Mittel: Er hat eine schwerwiegende Auswirkung.
• Hoch: Er hat eine katastrophale Auswirkung.',
    "IntegrityRequirementHelp" => "Wie wichtig die Integrität des betroffenen Assets für Ihr Unternehmen ist.\n• Niedrig: Ein Integritätsverlust hat begrenzte Auswirkungen.\n• Mittel: Er hat schwerwiegende Auswirkungen.\n• Hoch: Er hat katastrophale Auswirkungen.",
    "AvailabilityRequirementHelp" => 'Wie wichtig die Verfügbarkeit des betroffenen Assets für Ihre Organisation ist.
• Niedrig: Ein Verfügbarkeitsverlust hat eine begrenzte Auswirkung.
• Mittel: Er hat eine schwerwiegende Auswirkung.
• Hoch: Er hat eine katastrophale Auswirkung.',
    // Base Score Metrics' two sub-group intro sentences (metricsSubGroup()'s
    // `descKey`, risk-details-form.js) -- orient the user to what the GROUP
    // as a whole is asking, distinct from the per-field *Help popover keys
    // above which explain each metric's own options.
    'BaseScoreExploitabilityMetricsDescription' => 'Wie ein Angreifer diese Schwachstelle erreichen und auslösen müsste: wo er sich befinden muss, wie komplex der Angriff ist und ob er sich zuvor authentifizieren muss.',
    'BaseScoreImpactMetricsDescription' => 'Was passiert, wenn die Schwachstelle erfolgreich ausgenutzt wird: die Auswirkung auf die Vertraulichkeit, Integrität und Verfügbarkeit des betroffenen Systems.',
    // Advanced Metrics' three optional sub-group intro sentences -- same
    // metricsSubGroup() `descKey` as the two Base Score groups above.
    'TemporalScoreMetricsDescription' => 'Wie sich die Bedrohung durch diese Sicherheitslücke in der Praxis im Laufe der Zeit verändert: der aktuelle Stand des Exploit-Codes, welche Abhilfemaßnahmen verfügbar sind und wie sicher die Berichte über deren Existenz sind.',
    'EnvironmentalScoreMetricsDescription' => 'Wie das Risiko dieser Sicherheitslücke von Ihrer Umgebung abhängt: das Potenzial für reale Schäden und wie viele Ihrer Systeme tatsächlich betroffen sind.',
    'ImpactSubscoreModifiersDescription' => 'Gewichten Sie die Auswirkung der Basis-Punktzahl danach, wie wichtig Vertraulichkeit, Integrität und Verfügbarkeit für dieses spezifische Asset tatsächlich sind.',
    // Phase 4d-iii: DREAD holder help popovers (view_dread_help()'s
    // existing English text, includes/display.php, extracted to real $lang
    // keys -- that function's own content was raw hardcoded HTML, never
    // localized, so it could not be reused verbatim).
    'DamagePotentialHelp' => 'Wenn ein Bedrohungs-Exploit auftritt, wie großer Schaden wird verursacht?
0 = Nichts
5 = Daten einzelner Benutzer werden kompromittiert oder beeinträchtigt.
10 = Vollständige Zerstörung von System oder Daten',
    'ReproducibilityHelp' => 'Wie einfach ist es, den Bedrohungs-Exploit zu reproduzieren?
0 = Sehr schwer oder unmöglich, selbst für Administratoren der Anwendung.
5 = Ein oder zwei Schritte erforderlich, möglicherweise muss es ein autorisierter Benutzer sein.
10 = Ein Webbrowser und die Adressleiste genügen, ohne Authentifizierung.',
    'ExploitabilityHelp' => 'Was ist erforderlich, um diese Bedrohung auszunutzen?
0 = Fortgeschrittene Programmier- und Netzwerkkenntnisse mit benutzerdefinierten oder fortgeschrittenen Angriffswerkzeugen.
5 = Malware existiert im Internet, oder ein Exploit lässt sich mit verfügbaren Angriffswerkzeugen leicht durchführen.
10 = Nur ein Webbrowser',
    'AffectedUsersHelp' => 'Wie viele Benutzer sind betroffen?
0 = Keine
5 = Einige Benutzer, aber nicht alle
10 = Alle Benutzer',
    'DiscoverabilityHelp' => 'Wie einfach ist es, diese Bedrohung zu entdecken?
0 = Sehr schwer bis unmöglich; erfordert Quellcode oder administrativen Zugriff.
5 = Kann durch Raten oder durch Überwachung von Netzwerkmitschnitten herausgefunden werden.
9 = Details zu solchen Fehlern sind bereits öffentlich bekannt und lassen sich mit einer Suchmaschine leicht finden.
10 = Die Informationen sind in der Adressleiste des Webbrowsers oder in einem Formular sichtbar.',
    // The DREAD holder's summary card heading and "DREAD Metrics" card
    // heading. No existing key covers either (confirmed via grep before
    // adding).
    'DreadScore' => 'DREAD-Punktzahl',
    'DreadMetrics' => 'DREAD-Metriken',
    // Phase 4d-iv: OWASP holder help popovers (view_owasp_help()'s
    // existing English text, includes/display.php, extracted to real
    // $lang keys -- same never-localized-legacy-content extraction the
    // DREAD phase already did for its own 5 fields). Wording/levels
    // trued up against that function's real source text, not transcribed
    // from an earlier standard-methodology draft.
    'SkillLevelHelp' => 'Wie technisch versiert ist diese Gruppe von Bedrohungsakteuren?
1 = Keine technischen Fähigkeiten
3 = Einige technische Fähigkeiten
5 = Fortgeschrittener Computerbenutzer
6 = Netzwerk- und Programmierkenntnisse
9 = Fähigkeiten im Bereich Sicherheits-Penetrationstests',
    'MotiveHelp' => 'Wie motiviert ist diese Gruppe von Bedrohungsakteuren, diese Schwachstelle zu finden und auszunutzen?
1 = Geringe oder keine Belohnung
4 = Mögliche Belohnung
9 = Hohe Belohnung',
    'OpportunityHelp' => 'Welche Ressourcen und Gelegenheiten sind erforderlich, damit diese Gruppe von Bedrohungsakteuren diese Schwachstelle findet und ausnutzt?
0 = Voller Zugriff oder teure Ressourcen erforderlich
4 = Spezieller Zugriff oder spezielle Ressourcen erforderlich
7 = Etwas Zugriff oder einige Ressourcen erforderlich
9 = Kein Zugriff und keine Ressourcen erforderlich',
    'SizeHelp' => 'Wie groß ist diese Gruppe von Bedrohungsakteuren?
2 = Entwickler
2 = Systemadministratoren
