9 = Automatisierte Werkzeuge verfügbar',
    'EaseOfExploitHelp' => 'Wie einfach ist es für diese Gruppe von Bedrohungsakteuren, diese Schwachstelle tatsächlich auszunutzen?
1 = Theoretisch
3 = Schwierig
5 = Einfach
9 = Automatisierte Werkzeuge verfügbar',
    'AwarenessHelp' => 'Wie gut ist diese Schwachstelle dieser Gruppe von Bedrohungsakteuren bekannt?
1 = Unbekannt
4 = Verborgen
6 = Offensichtlich
9 = Öffentlich bekannt',
    'IntrusionDetectionHelp' => 'Wie wahrscheinlich ist es, dass ein Exploit erkannt wird?
