3 = Protokolliert und überprüft
8 = Protokolliert ohne Überprüfung
9 = Nicht protokolliert',
    'LossOfConfidentialityHelp' => 'Wie viele Daten könnten offengelegt werden und wie sensibel sind diese?' . "\n" . '2 = Minimale Offenlegung nicht sensibler Daten' . "\n" . '6 = Minimale Offenlegung kritischer Daten' . "\n" . '6 = Umfangreiche Offenlegung nicht sensibler Daten' . "\n" . '7 = Umfangreiche Offenlegung kritischer Daten' . "\n" . '9 = Alle Daten offengelegt',
    'LossOfIntegrityHelp' => 'Wie viele Daten könnten beschädigt werden und wie stark sind sie beschädigt?
1 = Wenige leicht beschädigte Daten
3 = Wenige schwer beschädigte Daten
5 = Umfangreiche leicht beschädigte Daten
7 = Umfangreiche schwer beschädigte Daten
9 = Alle Daten vollständig beschädigt',
    'LossOfAvailabilityHelp' => 'Wie viel Service könnte verloren gehen und wie wichtig ist er?
