    'AssetScoring' => 'Asset-Bewertung',
    'AssetScoringSettingsHint' => 'Jeder Vermögenswert wird für Vertraulichkeit, Integrität und Verfügbarkeit mit Niedrig, Mittel oder Hoch bewertet. Die Vertraulichkeit kann stattdessen Nicht zutreffend sein; dann wird sie in beiden Ergebnissen nicht berücksichtigt. Die FIPS-Kategorisierung entspricht der höchsten der drei Bewertungen. Die gewichtete Punktzahl ist der gewichtete Durchschnitt der drei Stufenwerte, und die Schwellenwerte der Bereiche ordnen diese Punktzahl einem Bereich Niedrig, Mittel oder Hoch zu. Eine Änderung dieser Einstellungen bewertet sofort alle Vermögenswerte neu.',
    'Weights' => 'Gewichtungen',
    'AssetScoringWeightsHint' => 'Wie stark jedes Ziel in die gewichtete Punktzahl eingeht: 0 bis 100, mit bis zu zwei Dezimalstellen. Eine Gewichtung von 0 schließt dieses Ziel aus. Integrität und Verfügbarkeit dürfen nicht beide 0 sein, da eine Vertraulichkeit mit Nicht zutreffend immer ausgeschlossen wird.',
    'LevelValues' => 'Stufenwerte',
    'AssetScoringLevelValuesHint' => 'Die Zahl, die jede Bewertung zur gewichteten Punktzahl beiträgt: größer als 0 und bis zu 100, mit bis zu zwei Dezimalstellen, wobei Niedrig unter Mittel und Mittel unter Hoch liegen muss. Die Standardwerte sind Niedrig 1, Mittel 2 und Hoch 3.',
    'BandThresholds' => 'Schwellenwerte der Bereiche',
    'AssetScoringBandThresholdsHint' => 'Eine gewichtete Punktzahl ab einem Schwellenwert gehört zu diesem Bereich, und eine Punktzahl unter dem Schwellenwert für Mittel gehört zu Niedrig. Mittel muss über dem Wert für Niedrig beginnen, und Hoch muss über Mittel beginnen und darf nicht über dem Wert für Hoch liegen.',
    'ModerateStartsAt' => 'Mittel beginnt bei',
    'HighStartsAt' => 'Hoch beginnt bei',
    'DefaultScoringForNewAssets' => 'Standardbewertung für neue Vermögenswerte',
    'AssetScoringDefaultsHint' => 'Diese Bewertungen werden automatisch ausgewählt, wenn jemand ein Asset im Asset-Formular hinzufügt. Assets, die per Discovery, Import oder API erstellt werden, bleiben unbewertet, sofern sie keine eigenen Bewertungen angeben. Lassen Sie alle drei Optionen auf „Nicht festgelegt“, um diese Funktion zu deaktivieren.',
    'AssetScoringWeightsInvalid' => 'Die Gewichtungen der Asset-Bewertung müssen Zahlen zwischen 0 und 100 mit höchstens zwei Dezimalstellen sein, und Integrität und Verfügbarkeit dürfen nicht beide 0 sein.',
    'AssetScoringValuesInvalid' => 'Die Stufenwerte für das Scoring von Vermögenswerten müssen Zahlen größer als 0 und bis zu 100 mit höchstens zwei Dezimalstellen sein, wobei Niedrig unter Mittel und Mittel unter Hoch liegen muss.',
    'AssetScoringThresholdsInvalid' => 'Die Schwellenwerte der Bereiche für das Scoring von Vermögenswerten dürfen höchstens zwei Dezimalstellen haben. Mittel muss über dem Wert für Niedrig beginnen, Hoch muss über Mittel beginnen, und Hoch darf nicht über dem Wert für Hoch beginnen.',
    'AssetScoringDefaultsInvalid' => 'Das Standard-Scoring für neue Vermögenswerte muss eine Stufe sein, die jedes Ziel anbietet.',
    'AssetScoringSettingsNotSaved' => 'Die Einstellungen für das Scoring von Vermögenswerten konnten nicht gespeichert werden. Es wurde nichts geändert.',
