    'AssetScoringNoWeightedScoreNote' => 'Keine gewichtete Punktzahl: Jedes berücksichtigte Ziel hat eine Gewichtung von 0.',
    'AssetScoringUpgradePending' => 'Das Scoring von Vermögenswerten kann erst gespeichert werden, nachdem das Datenbank-Upgrade von SimpleRisk ausgeführt wurde. Es wurde nichts geändert.',
    'AssetScoringResultHelpLabel' => 'Erklärung zu {$result}',
    'AssetScoringScoreHelp' => 'Die gewichtete Punktzahl kombiniert die drei Bewertungen zu einer Zahl zwischen {$low} und {$high}. Jede Bewertung erhält ihren festgelegten Wert, der mit der Gewichtung des jeweiligen Ziels multipliziert wird. Die Ergebnisse werden addiert und durch die Summe der Gewichtungen geteilt. Eine Vertraulichkeit mit dem Wert „Nicht zutreffend“ wird zusammen mit ihrer Gewichtung nicht berücksichtigt. Die festgelegten Werte und Gewichtungen werden in den Einstellungen konfiguriert. Alle drei Ziele müssen bewertet sein, bevor eine Punktzahl angezeigt wird.',
    'AssetScoringCategorizationHelp' => 'Die FIPS-199-Sicherheitskategorisierung ist der Höchstwert (High-Water-Mark): die höchste Bewertung unter den zutreffenden Zielen. Eine einzige Bewertung Hoch macht den Vermögenswert zu Hoch, unabhängig von den anderen. Nicht zutreffend wird ignoriert.',
    'AssetScoringBandHelp' => 'Die Stufe ordnet die gewichtete Punktzahl einer Skala aus Niedrig, Mittel oder Hoch zu. Eine Punktzahl unter {$moderate} ist Niedrig, von {$moderate} bis unter {$highAt} ist Mittel, und {$highAt} oder mehr ist Hoch. Die Schwellenwerte werden in den Einstellungen konfiguriert.',
