    'EnableHSTS' => 'HTTP Strict Transport Security (HSTS) aktivieren',
    'EnableHSTSHelp' => 'Weist Browser an, sich für die unten angegebene maximale Gültigkeitsdauer nur über HTTPS mit SimpleRisk zu verbinden. Aktivieren Sie diese Option erst, wenn HTTPS auf dieser Website zuverlässig funktioniert: Browser, die den Header erhalten haben, lehnen reines HTTP ab, und ein fehlerhaftes Zertifikat kann erst nach Ablauf der maximalen Gültigkeitsdauer umgangen werden. Starten Sie mit einer kurzen maximalen Gültigkeitsdauer, z. B. 300 Sekunden, und erhöhen Sie sie, sobald HTTPS überprüft ist.',
